draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw plane
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 20);
  ctx.lineTo(W/2, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2);
  ctx.lineTo(W/2 + 20, H/2);
  ctx.stroke();

  // draw wings
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 - 10);
  ctx.lineTo(W/2 - 30, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 10, H/2 - 10);
  ctx.lineTo(W/2 + 30, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 + 10);
  ctx.lineTo(W/2 - 30, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 10, H/2 + 10);
  ctx.lineTo(W/2 + 30, H/2);
  ctx.stroke();

  // draw tail
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 + 30);
  ctx.lineTo(W/2 + 10, H/2 + 30);
  ctx.stroke();

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20 * Math.sin(t), H/2 + 20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 30);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 70 + 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();

  ctx.restore();
}
